descriptor.templateCss:
#container tb-my-widget-widget {
    height: 100%;
    display: block;
}

#container tb-my-widget-widget .my-widget-content {
    /* your inner styling here */
    height: 100%;
    overflow: auto;
}

descriptor.controllerScript:
self.onInit = function () {
    // delegate init to your Angular component
    self.ctx.$scope.myWidget.onInit();
};

self.actionSources = function () {
    return {
        'my-action': {
            name: 'widget-action.myAction',
            multiple: false
        }
    };
};

self.typeParameters = function () {
    return {
        dataKeysOptional: true,
        datasourcesOptional: true,
        maxDatasources: 1,
        maxDataKeys: 0,
        singleEntity: true,
        previewWidth: '200px',
        previewHeight: '80px',
        embedTitlePanel: true,
        overflowVisible: true,
        hideDataSettings: true
    };
};

self.onDestroy = function () {
    // clean up if necessary
};
